// Valider et normaliser le payload entrant
// Format attendu : { prospects: [{first_name, linkedin_url, company, ...}] }
// Ou un tableau direct : [{...}, {...}]

const body = $input.item.json.body ?? $input.item.json;
const rawProspects = Array.isArray(body) ? body : (body.prospects ?? []);

if (!rawProspects.length) {
  throw new Error('Payload invalide : aucun prospect trouvé. Format attendu : { prospects: [...] } ou [...]');
}

const validated = [];
const errors = [];

for (const [idx, p] of rawProspects.entries()) {
  // Champs obligatoires
  if (!p.first_name) {
    errors.push({ index: idx, error: 'first_name manquant', raw: p });
    continue;
  }

  if (!p.linkedin_url && !p.instagram_username) {
    errors.push({ index: idx, error: 'linkedin_url ou instagram_username requis', raw: p });
    continue;
  }

  // Normalisation
  const normalized = {
    first_name: String(p.first_name).trim(),
    last_name: p.last_name ? String(p.last_name).trim() : null,
    company: p.company ? String(p.company).trim() : null,
    title: p.title ? String(p.title).trim() : null,
    linkedin_url: p.linkedin_url ? String(p.linkedin_url).trim().split('?')[0] : null,
    instagram_username: p.instagram_username ? String(p.instagram_username).replace('@', '').trim() : null,
    platform: p.instagram_username && !p.linkedin_url ? 'instagram' : 'linkedin',
    industry: p.industry ?? null,
    location: p.location ?? null,
    public_fact: p.public_fact ?? null,
    source: p.source ?? 'api_import',
    profile_score: parseInt(p.profile_score ?? 0, 10),
    tags: Array.isArray(p.tags) ? p.tags : [],
  };

  validated.push({ json: normalized });
}

if (errors.length > 0) {
  console.warn(`[IMPORT] ${errors.length} prospects ignorés:`, JSON.stringify(errors));
}

console.log(`[IMPORT] ${validated.length} prospects validés sur ${rawProspects.length}`);

if (validated.length === 0) {
  throw new Error(`Aucun prospect valide sur ${rawProspects.length} fournis. Erreurs : ${JSON.stringify(errors)}`);
}

return validated;

