const claudeResp = $input.item.json;
const prospect = $('Valider et normaliser les prospects').item.json;

// Parser la réponse Claude avec fallback
let qualification = {};
try {
  const text = claudeResp.content[0].text.trim();
  // Essayer JSON direct, puis extraction
  try {
    qualification = JSON.parse(text);
  } catch {
    const match = text.match(/({[\s\S]*})/);
    qualification = match ? JSON.parse(match[1]) : {};
  }
} catch (e) {
  console.warn('[QUALIFY] Parsing Claude échoué, fallback:', e.message);
  qualification = {
    score: prospect.profile_score ?? 0,
    icp_match: false,
    decision_maker: false,
    do_not_contact: false,
    company_size_estimate: 'unknown',
  };
}

// Fusionner prospect + qualification
const enriched = {
  ...prospect,
  profile_score: qualification.score ?? prospect.profile_score ?? 0,
  icp_match: qualification.icp_match ?? false,
  decision_maker: qualification.decision_maker ?? false,
  company_size_estimate: qualification.company_size_estimate ?? 'unknown',
  likely_pain_points: qualification.likely_pain_points ?? [],
  best_angle: qualification.best_angle ?? null,
  // Ne pas écraser un public_fact existant si Claude n'en trouve pas
  public_fact: qualification.public_fact || prospect.public_fact || null,
  do_not_contact: qualification.do_not_contact ?? false,
  do_not_contact_reason: qualification.do_not_contact_reason ?? null,
  status: (qualification.do_not_contact || qualification.score < 4) ? 'do_not_contact' : 'new',
  _qualificationRaw: qualification,
};

return [{ json: enriched }];

// Agréger les résultats pour la réponse webhook
const results = $input.all();

const summary = {
  total_processed: results.length,
  imported: results.filter(r => r.json.status !== 'do_not_contact').length,
  do_not_contact: results.filter(r => r.json.status === 'do_not_contact').length,
  high_priority: results.filter(r => (r.json.profile_score ?? 0) >= 8).length,
  timestamp: new Date().toISOString(),
};

console.log('[IMPORT COMPLETE]', JSON.stringify(summary));

return [{ json: summary }];
